program Counter;

{$APPTYPE CONSOLE}

type
  TCounter = class
    Count: Integer;
    Step: Integer;
    constructor Create(AStep: Integer);
    procedure Tick;
  end;

constructor TCounter.Create(AStep: Integer);
begin
  inherited Create;
  Count := 0;
  Step := AStep;
end;

procedure TCounter.Tick;
begin
  Count := Count + Step;
end;

var
  C: TCounter;
begin
  C := TCounter.Create(5);
  try
    C.Tick;
    C.Tick;
    C.Tick;
    Writeln(C.Count);
  finally
    C.Free;
  end;
end.

program Accounts;

{$APPTYPE CONSOLE}

type
  TAccount = class
  private
    FOwner: string;
    FBalance: Integer;
  public
    constructor Create(const AOwner: string);
    procedure Deposit(Amount: Integer);
    property Owner: string read FOwner write FOwner;
    property Balance: Integer read FBalance;
  end;

constructor TAccount.Create(const AOwner: string);
begin
  inherited Create;
  FOwner := AOwner;
  FBalance := 0;
end;

procedure TAccount.Deposit(Amount: Integer);
begin
  if Amount > 0 then
    FBalance := FBalance + Amount;
end;

var
  Acc: TAccount;
begin
  Acc := TAccount.Create('Ada');
  try
    Acc.Deposit(50);
    Acc.Deposit(-20);
    Acc.Deposit(30);
    Writeln(Acc.Owner, ': ', Acc.Balance);
    Acc.Owner := 'Ada L.';
    Writeln(Acc.Owner);
  finally
    Acc.Free;
  end;
end.

